<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('hr');$rows=$pdo->query("SELECT l.id_lowongan,l.judul_lowongan,d.nama_divisi,l.status, COUNT(la.id_lamaran) jumlah_pelamar FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi LEFT JOIN lamaran la ON la.id_lowongan=l.id_lowongan WHERE l.status IN ('Dipublikasikan','Ditutup') GROUP BY l.id_lowongan ORDER BY l.id_lowongan DESC")->fetchAll();page_header('Pelamar');?><table><tr><th>Lowongan</th><th>Divisi</th><th>Pelamar</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['judul_lowongan'])?></td><td><?=e($r['nama_divisi'])?></td><td><?=e($r['jumlah_pelamar'])?></td><td><?=e($r['status'])?></td><td><a class="btn" href="seleksi.php?id=<?=$r['id_lowongan']?>">Kelola Seleksi</a><?php if($r['status']==='Dipublikasikan'):?> <a class="btn danger" href="tutup_lowongan.php?id=<?=$r['id_lowongan']?>">Tutup</a><?php endif;?></td></tr><?php endforeach;?></table><?php page_footer();
